export async function runStatesPrecompute(seconds: number, dt: number | null = null) {
  if (!getWbCompareStateIds().length) {
    toast('请先在信号窗勾选要预计算的状态', 'error');
    return;
  }
  for (const id of getWbCompareStateIds().slice()) {
    const row = (getWbCacheStatus()?.states || []).find((item) => String(item.state_id) === id);
    const label = `预计算 ${row?.name || id}…`;
    try {
      const result = (await runPrecomputeWithProgress(
        () => api(ENDPOINTS.networkStatePrecompute, {
          method: 'POST',
          body: JSON.stringify(dt ? { state_id: id, seconds, dt } : { state_id: id, seconds }),
          timeoutMs: 600000,
        }),
        label,
      )) as { ok?: boolean; error?: string; frames?: number } | null;
      if (result && (result as any).cancelled) { toast(`${label}已停止（未完成）`, 'warn', 3000); continue; }
      if (result && result.ok === false) toast(`${label}失败：${result.error || '未知错误'}`, 'error', 7000);
    } catch (error) {
      toast(`${label}失败：${(error as Error)?.message || error}`, 'error', 7000);
    }
  }
  toast('预计算完成', 'ok', 2600);
  await refreshWbAnalysis();
}
